#include <iostream>
#include <string>
#include <algorithm>

using namespace std;

int lengthOfLastWord(string s) {
    int length = 0;
    int i = s.length() - 1;
    while (i >= 0 && s[i] == ' ') i--;
    while (i >= 0 && s[i] != ' ') {
        length++;
        i--;
    }
    return length;
}

int main() {
    string s; getline(cin, s);
    if (s.empty()) return 0;
    if (s[0] == '"' && s.back() == '"') s = s.substr(1, s.length() - 2);
    cout << lengthOfLastWord(s) << endl;
    return 0;
}

